package TaskB4;
import TaskB1.PassStore; import Task05.Db; import TaskB3.PassLoader; import java.nio.file.*; import java.io.*; import java.sql.*; import java.util.*;
public class Migrate { public static void main(String[] a)throws Exception{Path f=Path.of(a.length==0?"passes.csv":a[0]);List<String[]> good=new ArrayList<>();List<String> bad=new ArrayList<>();if(Files.exists(f))try(BufferedReader r=Files.newBufferedReader(f)){String line;int no=0;while((line=r.readLine())!=null){no++;String[] p=line.split(",",-1);try{if(p.length!=5)throw new IllegalArgumentException("expected 5 fields");Integer.parseInt(p[3]);Double.parseDouble(p[4]);good.add(p);}catch(Exception e){bad.add("line "+no+": "+e.getMessage());}}}try(Connection c=Db.connect()){System.out.println("Migrated rows="+PassLoader.loadAll(c,good));DatabaseMetaData m=c.getMetaData();System.out.println("DB="+m.getDatabaseProductName()+", driver="+m.getDriverVersion());try(ResultSet t=m.getTables(null,null,"%",new String[]{"TABLE"})){while(t.next())System.out.println("Table: "+t.getString("TABLE_NAME"));}}System.out.println("Rejected records:");bad.forEach(System.out::println);} }
